  ('house-base', 'Base', null, 'house', 1, false, null, '[]'::jsonb, null, 'The signature that started it all. Warm amber and precious woods, balanced with a whisper of spice — the scent of the House of Raza.', '[]'::jsonb),
  ('house-oud', 'Oud', null, 'house', 2, false, null, '[]'::jsonb, null, 'Smoked agarwood from ancient forests, deepened with leather and resin. A commanding trail that lingers long after you leave the room.', '[]'::jsonb),
  ('house-musk', 'Musk', null, 'house', 3, false, null, '[]'::jsonb, null, 'Clean white musk wrapped in soft florals and powdered iris — quiet, luminous and impossibly close to the skin.', '[]'::jsonb)
on conflict (id) do update set
  name        = excluded.name,
  sheet_name  = excluded.sheet_name,
  category    = excluded.category,
  number      = excluded.number,
  inspired    = excluded.inspired,
  price       = coalesce(excluded.price, public.products.price),
  -- sizes follow the sheet; a size the sheet leaves unpriced keeps a price set in the dashboard
  variants    = case when jsonb_array_length(excluded.variants) = 0 then public.products.variants else (
                  select jsonb_agg(case when jsonb_typeof(e.v -> 'price') = 'number' then e.v
                                        else e.v || jsonb_build_object('price', o.v -> 'price') end order by e.i)
                  from jsonb_array_elements(excluded.variants) with ordinality as e(v, i)
                  left join jsonb_array_elements(public.products.variants) as o(v) on o.v ->> 'id' = e.v ->> 'id'
                ) end,
  stock       = coalesce(excluded.stock, public.products.stock),
  description = coalesce(public.products.description, excluded.description),
  -- photos: the bundled ones only until photos are managed in the admin panel
  images      = case when jsonb_array_length(public.products.images) = 0 then excluded.images else public.products.images end;
